data = read('/input/data')
nodes = data['nodes']
ordered = sorted(nodes)
parent = {}
for node in ordered:
    parent = putmap(parent, node, node)
for edge in data['edges']:
    u = edge['u']
    v = edge['v']
    ru = u
    while ru != parent[ru]:
        ru = parent[ru]
    rv = v
    while rv != parent[rv]:
        rv = parent[rv]
    if ru != rv:
        if ru < rv:
            parent = putmap(parent, rv, ru)
        else:
            parent = putmap(parent, ru, rv)
groups = {}
for node in ordered:
    root = node
    while root != parent[root]:
        root = parent[root]
    groups = putmap(groups, root, get(groups, root, []) + [node])
components = sorted([groups[root] for root in keys(groups)], key=lambda component: component[0])
result = {'main': components}
